package net.civeira.phylax.feature.observe.observedprobe.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.valueobject.FailuresToAlertVO;

class FailuresToAlertValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of failures to alert of observed probe")
  void test_failures_to_alert_value_holder_assign_plain_value() {
    Object holder = new Object();
    FailuresToAlertValueHolder<Object> value = new FailuresToAlertValueHolder<>(holder);
    Assertions.assertSame(holder, value.failuresToAlert(1), "Setters must return the holder");
    Assertions.assertTrue(value.getFailuresToAlertValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getFailuresToAlert().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of failures to alert of observed probe")
  void test_failures_to_alert_value_holder_assign_value_object() {
    Object holder = new Object();
    FailuresToAlertValueHolder<Object> value = new FailuresToAlertValueHolder<>(holder);
    FailuresToAlertVO vo = FailuresToAlertVO.from(1);
    Assertions.assertFalse(value.getFailuresToAlertValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.failuresToAlert(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getFailuresToAlertValue().orElseThrow());
    Assertions.assertSame(holder, value.failuresToAlert(Optional.empty()));
    Assertions.assertFalse(value.getFailuresToAlertValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.failuresToAlert(Optional.of(vo)));
    Assertions.assertSame(vo, value.getFailuresToAlertValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of failures to alert of observed probe against the original")
  void test_failures_to_alert_value_holder_read() {
    Object holder = new Object();
    FailuresToAlertValueHolder<Object> value = new FailuresToAlertValueHolder<>(holder);
    FailuresToAlertVO vo = FailuresToAlertVO.from(1);
    FailuresToAlertVO other = FailuresToAlertVO.from(1);
    ObservedProbe original = Mockito.mock(ObservedProbe.class);
    Mockito.when(original.getFailuresToAlertValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readFailuresToAlert(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readFailuresToAlert(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.failuresToAlert(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readFailuresToAlert(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readFailuresToAlert(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of failures to alert of observed probe")
  void test_failures_to_alert_value_holder_unset() {
    Object holder = new Object();
    FailuresToAlertValueHolder<Object> value = new FailuresToAlertValueHolder<>(holder);
    FailuresToAlertVO vo = FailuresToAlertVO.from(1);
    value.failuresToAlert(vo);
    Assertions.assertSame(holder, value.unsetFailuresToAlertIfMatches("failuresToAlert_other"));
    Assertions.assertTrue(value.getFailuresToAlertValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetFailuresToAlertIfMatches("failuresToAlert"));
    Assertions.assertFalse(value.getFailuresToAlertValue().isPresent(),
        "The field name must clear the value");
    value.failuresToAlert(vo);
    Assertions.assertSame(holder, value.unsetFailuresToAlert());
    Assertions.assertFalse(value.getFailuresToAlertValue().isPresent(),
        "Unset must clear the value");
  }
}
